steps.drag:
(() => {
  const ann = [...a.annotations.values()][0];
  const bp = a.renderer.projectWorld(ann.worldX + ann.offsetX, ann.worldY + ann.offsetY);
  const plotRect = document.querySelector('.plot').getBoundingClientRect();
  const sx = plotRect.left + bp[0] + 20;
  const sy = plotRect.top + bp[1] + 10;
  return [[sx, sy], [sx + 60, sy - 30], [sx + 60, sy - 30]];
})()
